package com.eventfinder.service;
import com.eventfinder.dao.UserDao; import com.eventfinder.dto.*; import com.eventfinder.model.User; import com.eventfinder.security.JwtService; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service;
@Service public class AuthService {private final UserDao dao;private final PasswordEncoder encoder;private final JwtService jwt;public AuthService(UserDao d,PasswordEncoder e,JwtService j){dao=d;encoder=e;jwt=j;}public TokenResponse register(RegisterRequest r){if(dao.byEmail(r.email()).isPresent())throw new IllegalArgumentException("An account with this email already exists");User u=dao.create(r.name(),r.email(),encoder.encode(r.password()));return new TokenResponse(jwt.generate(u.email(),u.role()),u);}public TokenResponse login(AuthRequest r){User u=dao.byEmail(r.email()).orElseThrow(()->new IllegalArgumentException("Invalid email or password"));if(!encoder.matches(r.password(),dao.password(r.email())))throw new IllegalArgumentException("Invalid email or password");return new TokenResponse(jwt.generate(u.email(),u.role()),u);} }